package com.bitedash.controller; import com.bitedash.dto.*; import com.bitedash.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/register") public ResponseEntity<UserResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(r));} @PostMapping("/login") public UserResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);}}
